shellCommands.command:
(npx vite --port 5173 --strictPort > /tmp/e2e/vite.log 2>&1 &) ; sleep 4; cat /tmp/e2e/vite.log; cat > /tmp/e2e/check.mjs <<'EOF'
import { chromium } from 'playwright';

const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
await page.goto('http://localhost:5173/', { waitUntil: 'networkidle' });

const toastSel = '[data-toast]';
const count = () => page.locator(toastSel).count();
console.log('toasts before click:', await count());

await page.getByRole('button', { name: 'Показать уведомление' }).click();
await page.waitForSelector(toastSel, { timeout: 2000 });
console.log('toasts after 1 click:', await count());
console.log('toast text:', (await page.locator(toastSel).first().innerText()).replace(/\n/g, ' | '));
await page.screenshot({ path: '/tmp/e2e/shown.png' });

await page.waitForTimeout(2000);
console.log('toasts at +2s (should still be 1):', await count());

await page.waitForTimeout(3000);
console.log('toasts at +5s (should be 0):', await count());

await page.getByRole('button', { name: 'Показать уведомление' }).click();
await page.getByRole('button', { name: 'Показать уведомление' }).click();
console.log('toasts after 2 more clicks:', await count());
await page.waitForTimeout(5000);
console.log('toasts after auto-hide:', await count());

const box = await page.getByRole('button', { name: 'Показать уведомление' }).boundingBox();
console.log('button box (viewport 1000x700):', JSON.stringify(box));
console.log('errors:', errors);
await browser.close();
EOF
cd /tmp/e2e && timeout 120 node check.mjs 2>&1 | tail -30

