  const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Показать'));
  const r = btn.getBoundingClientRect();
  const x = r.left + r.width / 2, y = r.top + r.height / 2;
  const hit = document.elementFromPoint(x, y);
  const portal = document.querySelector('[data-floating-ui-portal]');
  return {
    btnRect: r.toJSON(), hit: hit && hit.outerHTML.slice(0, 200), hitChain: (() => { const out = []; let e = hit; while (e && out.length < 6) { out.push(e.tagName + '.' + (e.className && e.className.baseVal === undefined ? e.className : '')); e = e.parentElement; } return out; })(),
    portalHTML: portal ? portal.outerHTML.slice(0, 1500) : null,
  };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();
EOF
