cd /tmp/e2e && source env.sh && export PLAYWRIGHT_SKIP_VALIDATE_HOST_REQUIREMENTS=1 && cat > experiment.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
await page.goto('http://localhost:5190/', { waitUntil: 'load' });
await page.waitForTimeout(800);
const measure = () => page.evaluate(() => {
  const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Показать'));
  const wrap = btn.parentElement;
  return { wrapW: wrap.getBoundingClientRect().width, btnW: btn.getBoundingClientRect().width, spanW: btn.querySelector('span').getBoundingClientRect().width, wrapCss: wrap.getAttribute('style') };
});
console.log('as-is', JSON.stringify(await measure()));
await page.evaluate(() => { const w = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Показать')).parentElement; w.style.width = 'max-content'; });
console.log('wrapper width:max-content', JSON.stringify(await measure()));
await page.evaluate(() => { const w = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Показать')).parentElement; w.style.width = ''; w.style.left = 'auto'; });
const btn = await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Показать')); b.classList.remove('g-button_width_auto'); return { ok: true }; });
console.log('no width_auto class', JSON.stringify(await measure()));
await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Показать')); b.querySelector('span').style.display='inline'; });
console.log('span inline', JSON.stringify(await measure()));
await browser.close();
EOF
